"""Original bilingual explanations with small executable Python/JavaScript examples.

The legacy term/ru/uz fields remain available to clients using the first glossary.
Examples contain curated code, never code supplied by a user.
"""


def text(ru, uz):
    return {"ru": ru, "uz": uz}


CATEGORIES = {
    "basics": text("Основы", "Asoslar"),
    "input-output": text("Ввод и вывод", "Kiritish va chiqarish"),
    "conditions": text("Условия и логика", "Shartlar va mantiq"),
    "loops": text("Циклы", "Sikllar"),
    "collections": text("Строки и коллекции", "Matn va to‘plamlar"),
    "functions": text("Функции", "Funksiyalar"),
    "testing": text("Ошибки и проверка", "Xatolar va tekshirish"),
}


def example(code, output, ru, uz, stdin=""):
    return {"code": code, "stdin": stdin, "expected_stdout": output,
            "explanation": text(ru, uz)}


def entry(term, title_ru, title_uz, category, ru, uz, purpose_ru, purpose_uz, py, js):
    return {"term": term, "title": text(title_ru, title_uz), "category": category,
            "category_title": CATEGORIES[category], "ru": ru, "uz": uz,
            "purpose": text(purpose_ru, purpose_uz),
            "examples": {"Python": py, "JavaScript": js}}


